package net.civeira.phylax.feature.observe.observedfingerprintrule.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.event.ObservedFingerprintRuleEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedFingerprintRuleEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedFingerprintRuleEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedFingerprintRule entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
